// Generated by grafana-k6 on 2026-11-09T20:18:21Z
// Stress test of read-only public endpoints of the Amira demo backend.
// Closed model: ramps virtual users (think time 3-5 s) up to 300 and aborts
// as soon as the error rate or p95 latency crosses the agreed limits.
import http from 'k6/http';
import { check, sleep } from 'k6';
import { textSummary } from 'https://jslib.k6.io/k6-summary/0.1.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'https://amira-1hfu.onrender.com';
const PROFILE_ID = __ENV.PROFILE_ID || '8e9b74df-3306-4081-aeaf-8a5405a4346e';

// Weighted endpoint mix: 30 % /health (no database), 70 % database reads.
const ENDPOINTS = [
  { name: 'health', path: '/health', weight: 30 },
  { name: 'services', path: '/api/services', weight: 30 },
  { name: 'service-types', path: '/api/service-types', weight: 15 },
  { name: 'provider', path: `/api/providers/${PROFILE_ID}`, weight: 15 },
  { name: 'locations', path: '/api/locations', weight: 10 },
];

const TOTAL_WEIGHT = ENDPOINTS.reduce((sum, e) => sum + e.weight, 0);

export const options = {
  scenarios: {
    stress: {
      executor: 'ramping-vus',
      startVUs: 1,
      stages: [
        { duration: '1m', target: 1 }, // warm-up
        { duration: '30s', target: 10 },
        { duration: '1m', target: 10 },
        { duration: '30s', target: 25 },
        { duration: '1m', target: 25 },
        { duration: '30s', target: 50 },
        { duration: '1m', target: 50 },
        { duration: '30s', target: 100 },
        { duration: '1m', target: 100 },
        { duration: '30s', target: 200 },
        { duration: '1m', target: 200 },
        { duration: '30s', target: 300 },
        { duration: '1m', target: 300 },
        { duration: '30s', target: 0 },
      ],
      gracefulRampDown: '10s',
    },
  },
  thresholds: {
    http_req_failed: [{ threshold: 'rate<0.05', abortOnFail: true, delayAbortEval: '30s' }],
    http_req_duration: [{ threshold: 'p(95)<3000', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{endpoint:health}': ['p(95)<3000'],
    'http_req_duration{endpoint:services}': ['p(95)<3000'],
    'http_req_duration{endpoint:service-types}': ['p(95)<3000'],
    'http_req_duration{endpoint:provider}': ['p(95)<3000'],
    'http_req_duration{endpoint:locations}': ['p(95)<3000'],
  },
  summaryTrendStats: ['avg', 'min', 'med', 'p(90)', 'p(95)', 'p(99)', 'max'],
};

function pickEndpoint() {
  let roll = Math.random() * TOTAL_WEIGHT;
  for (const endpoint of ENDPOINTS) {
    roll -= endpoint.weight;
    if (roll < 0) return endpoint;
  }
  return ENDPOINTS[0];
}

export default function () {
  const endpoint = pickEndpoint();
  const res = http.get(`${BASE_URL}${endpoint.path}`, {
    tags: { endpoint: endpoint.name },
    timeout: '30s',
  });
  check(res, { 'status is 200': (r) => r.status === 200 }, { endpoint: endpoint.name });
  sleep(3 + Math.random() * 2);
}

export function handleSummary(data) {
  const out = __ENV.SUMMARY_JSON || 'k6-summary.json';
  return {
    stdout: textSummary(data, { indent: ' ', enableColors: false }),
    [out]: JSON.stringify(data, null, 2),
  };
}
